"""Embed the existing normalized test WAVs verbatim; no audio generation/editing."""
from pathlib import Path
import hashlib
import json
import wave

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / "sdcard/homehub/voices"
destination = ROOT / "firmware/src/homehub_seed_assets.c"
names = ("arrive.wav", "leave.wav", "take_key.wav")
parts = [
    '/* Generated by firmware/tools/embed_seed_assets.py.\n'
    ' * Original ordinary Mandarin test TTS, not real-person or dialect audio.\n'
    ' * Arrays are const and remain in the firmware read-only image. */\n'
    '#include "homehub_seed.h"\n'
]
manifest = []
for index, name in enumerate(names):
    path = source / name
    payload = path.read_bytes()
    with wave.open(str(path), "rb") as wav:
        assert (wav.getnchannels(), wav.getsampwidth(), wav.getframerate(), wav.getcomptype()) == (1, 2, 16000, "NONE")
        assert len(payload) == 44 + wav.getnframes() * 2
    digest = hashlib.sha256(payload).hexdigest()
    manifest.append({"name": name, "bytes": len(payload), "sha256": digest})
    parts.append(f"/* {name}: {len(payload)} bytes, SHA256 {digest} */\n")
    parts.append(f"static const uint8_t seed_voice_{index}[] = {{\n")
    parts.extend("    " + ",".join(f"0x{x:02x}" for x in payload[n:n+16]) + ",\n" for n in range(0, len(payload), 16))
    parts.append("};\n")
parts.append("const HH_SeedAsset hh_seed_assets[] = {\n")
parts.extend(f'    {{"{name}", seed_voice_{index}, sizeof(seed_voice_{index})}},\n' for index, name in enumerate(names))
parts.append("};\nconst size_t hh_seed_asset_count = sizeof(hh_seed_assets) / sizeof(hh_seed_assets[0]);\n")
destination.write_text("".join(parts), encoding="utf-8")
destination.with_suffix(".json").write_text(json.dumps({"source": "existing normalized ordinary Mandarin test WAVs", "assets": manifest}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(json.dumps({"destination": str(destination), "wav_bytes": sum(item["bytes"] for item in manifest), "assets": manifest}, ensure_ascii=False, indent=2))
